impl TextEdit {
    pub fn compare(&self, other: &TextEdit) -> std::cmp::Ordering {
        let c = self.range.compare(&other.range);
        if c != std::cmp::Ordering::Equal {
            return c;
        }
        cmp_compare(&self.new_text, &other.new_text)
    }
}

