// A range in a text document expressed as (zero-based) start and end positions.
//
// If you want to specify a range that contains a line including the line ending
// character(s) then use an end position denoting the start of the next line.
// For example:
// ```ts
// {
//  start: { line: 5, character: 23 }
//  end : { line 6, character : 0 }
// }
// ```
#[derive(Clone, Debug, Default, PartialEq, Copy, Eq, Hash)]
pub struct Range {
    // The range's start position.
    pub start: Position,

    // The range's end position.
    pub end: Position,
}

impl Json for Range {
    const GO_TYPE: &'static str = "lsproto.Range";

    fn to_json(&self) -> Value {
        let mut w = ObjectWriter::new(2);
        w.field("start", &self.start);
        w.field("end", &self.end);
        w.finish()
    }

    fn from_json(v: &Value) -> Result<Self, JsonError> {
        let mut s = Self::default();
        let Some(members) = struct_members(v, Self::GO_TYPE, true)? else {
            return Ok(s);
        };
        let mut seen = 0u64;
        for (k, v) in members {
            match k {
                "start" => {
                    seen |= 1 << 0;
                    s.start = field(k, v)?;
                }
                "end" => {
                    seen |= 1 << 1;
                    s.end = field(k, v)?;
                }
                _ => {}
            }
        }
        check_required(seen, &["start", "end"], Self::GO_TYPE)?;
        Ok(s)
    }
}

impl Range {
    fn compare(&self, other: &Range) -> std::cmp::Ordering {
        let c = self.start.compare(other.start);
        if c != std::cmp::Ordering::Equal {
            return c;
        }
        self.end.compare(other.end)
    }
}

