// A string value used as a snippet is a template which allows to insert text
// and to control the editor cursor when insertion happens.
//
// A snippet can define tab stops and placeholders with `$1`, `$2`
// and `${3:foo}`. `$0` defines the final tab stop, it defaults to
// the end of the snippet. Variables are defined with `$name` and
// `${name:default value}`.
//
// Since: 3.18.0
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct StringValue {
    // The kind of string value.
    kind: StringLiteralSnippet,

    // The snippet string.
    value: String,
}

impl Json for StringValue {
    const GO_TYPE: &'static str = "lsproto.StringValue";
    const GO_POINTER: bool = true;

    fn to_json(&self) -> Value {
        let mut w = ObjectWriter::new(2);
        w.field("kind", &self.kind);
        w.field("value", &self.value);
        w.finish()
    }

    fn from_json(v: &Value) -> Result<Self, JsonError> {
        let mut s = Self::default();
        let Some(members) = struct_members(v, Self::GO_TYPE, true)? else {
            return Ok(s);
        };
        let mut seen = 0u64;
        for (k, v) in members {
            match k {
                "kind" => {
                    seen |= 1 << 0;
                    s.kind = field(k, v)?;
                }
                "value" => {
                    seen |= 1 << 1;
                    s.value = field(k, v)?;
                }
                _ => {}
            }
        }
        check_required(seen, &["kind", "value"], Self::GO_TYPE)?;
        Ok(s)
    }
}

