// A relative pattern is a helper to construct glob patterns that are matched
// relatively to a base URI. The common value for a `baseUri` is a workspace
// folder root, but it can be another absolute URI as well.
//
// Since: 3.17.0
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct RelativePattern {
    // A workspace folder or a base URI to which this pattern will be matched
    // against relatively.
    pub base_uri: WorkspaceFolderOrURI,

    // The actual glob pattern;
    pub pattern: String,
}

impl Json for RelativePattern {
    const GO_TYPE: &'static str = "lsproto.RelativePattern";
    const GO_POINTER: bool = true;

    fn to_json(&self) -> Value {
        let mut w = ObjectWriter::new(2);
        w.field("baseUri", &self.base_uri);
        w.field("pattern", &self.pattern);
        w.finish()
    }

    fn from_json(v: &Value) -> Result<Self, JsonError> {
        let mut s = Self::default();
        let Some(members) = struct_members(v, Self::GO_TYPE, true)? else {
            return Ok(s);
        };
        let mut seen = 0u64;
        for (k, v) in members {
            match k {
                "baseUri" => {
                    seen |= 1 << 0;
                    s.base_uri = field(k, v)?;
                }
                "pattern" => {
                    seen |= 1 << 1;
                    s.pattern = field(k, v)?;
                }
                _ => {}
            }
        }
        check_required(seen, &["baseUri", "pattern"], Self::GO_TYPE)?;
        Ok(s)
    }
}

