// Predefined error codes.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct ErrorCode(pub i32);

impl ErrorCode {
    pub const PARSE_ERROR: ErrorCode = ErrorCode(-32700);
    pub const INVALID_REQUEST: ErrorCode = ErrorCode(-32600);
    pub const METHOD_NOT_FOUND: ErrorCode = ErrorCode(-32601);
    pub const INVALID_PARAMS: ErrorCode = ErrorCode(-32602);
    pub const INTERNAL_ERROR: ErrorCode = ErrorCode(-32603);
    // Error code indicating that a server received a notification or
    // request before the server has received the `initialize` request.
    pub const SERVER_NOT_INITIALIZED: ErrorCode = ErrorCode(-32002);
    pub const UNKNOWN_ERROR_CODE: ErrorCode = ErrorCode(-32001);
    // A request failed but it was syntactically correct, e.g the
    // method name was known and the parameters were valid. The error
    // message should contain human readable information about why
    // the request failed.
    //
    // Since: 3.17.0
    pub const REQUEST_FAILED: ErrorCode = ErrorCode(-32803);
    // The server cancelled the request. This error code should
    // only be used for requests that explicitly support being
    // server cancellable.
    //
    // Since: 3.17.0
    pub const SERVER_CANCELLED: ErrorCode = ErrorCode(-32802);
    // The server detected that the content of a document got
    // modified outside normal conditions. A server should
    // NOT send this error code if it detects a content change
    // in it unprocessed messages. The result even computed
    // on an older state might still be useful for the client.
    //
    // If a client decides that a result is not of any use anymore
    // the client should cancel the request.
    pub const CONTENT_MODIFIED: ErrorCode = ErrorCode(-32801);
    // The client has canceled a request and a server has detected
    // the cancel.
    pub const REQUEST_CANCELLED: ErrorCode = ErrorCode(-32800);
}

impl ErrorCode {
    pub fn string(self) -> String {
        match self.0 {
            -32803 => "RequestFailed".to_string(),
            -32802 => "ServerCancelled".to_string(),
            -32801 => "ContentModified".to_string(),
            -32800 => "RequestCancelled".to_string(),
            -32700 => "ParseError".to_string(),
            -32603 => "InternalError".to_string(),
            -32602 => "InvalidParams".to_string(),
            -32601 => "MethodNotFound".to_string(),
            -32600 => "InvalidRequest".to_string(),
            -32002 => "ServerNotInitialized".to_string(),
            -32001 => "UnknownErrorCode".to_string(),
            _ => format!("ErrorCode({})", self.0),
        }
    }
}

impl fmt::Display for ErrorCode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.string())
    }
}

impl std::error::Error for ErrorCode {}

impl Json for ErrorCode {
    const GO_TYPE: &'static str = "lsproto.ErrorCode";

    fn to_json(&self) -> Value {
        Value::Number(self.0 as f64)
    }

    fn from_json(v: &Value) -> Result<Self, JsonError> {
        crate::json::decode_int(v, 32, Self::GO_TYPE).map(|n| ErrorCode(n as i32))
    }
}

impl IsZero for ErrorCode {
    fn is_zero(&self) -> bool {
        self.0 == 0
    }
}

