// Defines whether the insert text in a completion item should be interpreted as
// plain text or a snippet.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct InsertTextFormat(u32);

impl InsertTextFormat {
    // The primary text to be inserted is treated as a plain string.
    pub const PLAIN_TEXT: InsertTextFormat = InsertTextFormat(1);
    // The primary text to be inserted is treated as a snippet.
    //
    // A snippet can define tab stops and placeholders with `$1`, `$2`
    // and `${3:foo}`. `$0` defines the final tab stop, it defaults to
    // the end of the snippet. Placeholders with equal identifiers are linked,
    // that is typing in one will update others too.
    //
    // See also: https://microsoft.github.io/language-server-protocol/specifications/specification-current/#snippet_syntax
    pub const SNIPPET: InsertTextFormat = InsertTextFormat(2);
}

impl InsertTextFormat {
    fn string(self) -> String {
        match self.0 {
            1 => "PlainText".to_string(),
            2 => "Snippet".to_string(),
            _ => format!("InsertTextFormat({})", self.0),
        }
    }
}

impl fmt::Display for InsertTextFormat {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.string())
    }
}

impl Json for InsertTextFormat {
    const GO_TYPE: &'static str = "lsproto.InsertTextFormat";

    fn to_json(&self) -> Value {
        Value::Number(self.0 as f64)
    }

    fn from_json(v: &Value) -> Result<Self, JsonError> {
        crate::json::decode_uint(v, 32, Self::GO_TYPE).map(|n| InsertTextFormat(n as u32))
    }
}

